<?php
$severityCounts=['high'=>0,'medium'=>0,'low'=>0];
foreach($db->query("SELECT priority,COUNT(*) n FROM incidents GROUP BY priority") as $r){$key=$r['priority']==='critical'?'high':$r['priority'];$severityCounts[$key]=(int)$r['n']+($severityCounts[$key]??0);}
$totalIncidents=array_sum($severityCounts);$highEnd=$totalIncidents?100*$severityCounts['high']/$totalIncidents:0;$mediumEnd=$totalIncidents?$highEnd+100*$severityCounts['medium']/$totalIncidents:0;
$resolved=(int)$db->query("SELECT COUNT(*) FROM incidents WHERE status IN ('resolved','closed')")->fetchColumn();$resolvedPercent=$totalIncidents?round(100*$resolved/$totalIncidents):0;
?>

<?php if(in_array($page,['overview','reports'])): ?>
<div class="live-chart-grid">
<article class="panel restored-chart"><div class="panel-heading"><div><h2>Incident severity</h2><p>All recorded incidents by priority</p></div></div><div class="category-content"><div class="donut" style="background:conic-gradient(#f2677a 0% <?=$highEnd?>%,#a855f7 <?=$highEnd?>% <?=$mediumEnd?>%,<?=$totalIncidents?'#4f7cff':'#2a3549'?> <?=$mediumEnd?>% 100%)"><div><b><?=$totalIncidents?></b><span>INCIDENTS</span></div></div><div class="category-legend"><?php foreach($severityCounts as $key=>$n):?><div><span><i class="dot <?=$key==='high'?'rose':($key==='medium'?'purple':'blue')?>-bg"></i><?=h(ucfirst($key))?></span><b><?=$n?></b></div><?php endforeach;?></div></div></article>
<article class="panel restored-chart"><div class="panel-heading"><div><h2>Incident resolution</h2><p>Resolved and closed incidents</p></div></div><div class="category-content"><div class="donut" style="background:conic-gradient(#54d6a0 <?=$resolvedPercent?>%,#2a3549 0)"><div><b><?=$resolvedPercent?>%</b><span>RESOLVED</span></div></div><div class="category-legend"><div><span>Open / investigating</span><b><?=$open?></b></div><div><span>Resolved / closed</span><b><?=$resolved?></b></div></div></div></article>
<article class="panel restored-chart wide"><div class="panel-heading"><div><h2>Seven-day activity trend</h2><p>Actual collected events per day</p></div></div><?php $days=[];for($i=6;$i>=0;$i--)$days[date('Y-m-d',strtotime('-'.$i.' days'))]=0;foreach($db->query('SELECT DATE(occurred_at) d,COUNT(*) n FROM security_events WHERE occurred_at>=CURDATE()-INTERVAL 6 DAY GROUP BY d') as $r)$days[$r['d']]=(int)$r['n'];$peak=max(1,max($days));$points=[];$i=0;foreach($days as $n){$points[]=(20+$i++*120).','.round(160-130*$n/$peak);} ?><svg viewBox="0 0 760 185" role="img" aria-label="Seven day event trend; daily totals listed below" class="live-trend"><path d="M20 30H740 M20 95H740 M20 160H740" stroke="#2a3549" fill="none"/><polygon points="20,160 <?=implode(' ',$points)?> 740,160" fill="#a855f722"/><polyline points="<?=implode(' ',$points)?>" fill="none" stroke="#b47aff" stroke-width="3"/><?php foreach($points as $point):[$x,$y]=explode(',',$point);?><circle cx="<?=$x?>" cy="<?=$y?>" r="4" fill="#c4a2ff"/><?php endforeach;?></svg><div class="live-trend-labels"><?php foreach($days as $day=>$n):?><span><?=h(date('M j',strtotime($day)))?><b><?=$n?></b></span><?php endforeach;?></div></article>
<?php if($page==='overview'): ?><article class="panel restored-chart overview-recent"><div class="panel-heading"><div><h2>Recent security events</h2><p>Latest activity from the connected student portal</p></div></div><?php live_table(['Time','Event','Account','IP','Severity'],$db->query('SELECT occurred_at,event_type,user_identifier,source_ip,severity FROM security_events ORDER BY id DESC LIMIT 6')->fetchAll(PDO::FETCH_NUM));?></article><?php endif;?>
</div>
<?php else: ?>
<div class="metrics module-summary"><?php $summaries=['events'=>['Collected events'=>(int)$db->query('SELECT COUNT(*) FROM security_events')->fetchColumn(),'Events today'=>$counts['total'],'Failed logins today'=>$counts['failed']], 'auth'=>['Administrator accounts'=>1,'Student accounts'=>1,'Separate session roles'=>2], 'source'=>['Connected source'=>1,'Events today'=>$counts['total'],'Database'=>'MySQL'], 'rules'=>['Active rules'=>3,'Incidents today'=>$threats,'Deduplication'=>'10 min'], 'incidents'=>['Total incidents'=>$totalIncidents,'Open incidents'=>$open,'Resolved'=>$resolved], 'alerts'=>['Local alerts'=>(int)$db->query('SELECT COUNT(*) FROM security_alerts')->fetchColumn(),'Gmail delivery'=>'Not configured','Sent emails'=>0], 'health'=>['Database'=>'Connected','Collection'=>'On request','Refresh'=>'15 sec']];foreach($summaries[$page]??[] as $label=>$value):?><article class="metric-card"><span class="metric-label"><?=h($label)?></span><strong><?=h($value)?></strong></article><?php endforeach;?></div>
<?php endif;?>
